    'Buscando horas libres…' => ['en' => 'Looking for available times…', 'pt' => 'A procurar horas livres…', 'gl' => 'Buscando horas libres…'],
    'Faltan tu nombre y un teléfono móvil.' => ['en' => 'Your name and a mobile number are missing.', 'pt' => 'Faltam o seu nome e um telemóvel.', 'gl' => 'Faltan o teu nome e un teléfono móbil.'],
    'Falta tu nombre.' => ['en' => 'Your name is missing.', 'pt' => 'Falta o seu nome.', 'gl' => 'Falta o teu nome.'],
    'Falta un teléfono móvil.' => ['en' => 'A mobile number is missing.', 'pt' => 'Falta um telemóvel.', 'gl' => 'Falta un teléfono móbil.'],
    'Marca la casilla para aceptar las políticas.' => ['en' => 'Tick the box to accept the policies.', 'pt' => 'Assinale a caixa para aceitar as políticas.', 'gl' => 'Marca a caixa para aceptar as políticas.'],
    'Enviando…' => ['en' => 'Sending…', 'pt' => 'A enviar…', 'gl' => 'Enviando…'],
    'Petición realizada' => ['en' => 'Request sent', 'pt' => 'Pedido enviado', 'gl' => 'Petición feita'],
    'Esperando confirmación. Mientras no abras el enlace del WhatsApp y pulses «Confirmar mi reserva», la reserva queda pendiente.' => ['en' => 'Waiting for confirmation. Until you open the WhatsApp link and tap “Confirm my booking”, the booking stays pending.', 'pt' => 'À espera de confirmação. Enquanto não abrir a ligação do WhatsApp e tocar em «Confirmar a minha reserva», a reserva fica pendente.', 'gl' => 'Agardando confirmación. Mentres non abras a ligazón do WhatsApp e premas «Confirmar a miña reserva», a reserva queda pendente.'],
    'Esperando confirmación. La verás en <a href="cuenta.php">tu cuenta</a>, donde también podrás cancelarla.' => ['en' => 'Waiting for confirmation. You’ll see it in <a href="cuenta.php">your account</a>, where you can also cancel it.', 'pt' => 'À espera de confirmação. Vai vê-la na <a href="cuenta.php">sua conta</a>, onde também a pode cancelar.', 'gl' => 'Agardando confirmación. Verala na <a href="cuenta.php">túa conta</a>, onde tamén poderás cancelala.'],
    'Si creas una cuenta con el mismo email, también la verás allí.' => ['en' => 'If you create an account with the same email, you’ll see it there too.', 'pt' => 'Se criar uma conta com o mesmo email, também a verá lá.', 'gl' => 'Se creas unha conta co mesmo correo, tamén a verás alí.'],
    'Como no has puesto email, esta reserva no aparecerá en ninguna cuenta.' => ['en' => 'As you didn’t give an email, this booking won’t appear in any account.', 'pt' => 'Como não indicou email, esta reserva não aparecerá em nenhuma conta.', 'gl' => 'Como non puxeches correo, esta reserva non aparecerá en ningunha conta.'],
    'Un momento…' => ['en' => 'One moment…', 'pt' => 'Um momento…', 'gl' => 'Un momento…'],
    'Datos guardados' => ['en' => 'Details saved', 'pt' => 'Dados guardados', 'gl' => 'Datos gardados'],
    'Email enviado otra vez' => ['en' => 'Email sent again', 'pt' => 'Email enviado novamente', 'gl' => 'Correo enviado outra vez'],
    '¿Cancelar la reserva del %s?' => ['en' => 'Cancel the booking for %s?', 'pt' => 'Cancelar a reserva de %s?', 'gl' => 'Cancelar a reserva do %s?'],
    '%s · página %s de %s' => ['en' => '%s · page %s of %s', 'pt' => '%s · página %s de %s', 'gl' => '%s · páxina %s de %s'],
    'Puedes cambiar tu elección cuando quieras.' => ['en' => 'You can change your choice at any time.', 'pt' => 'Pode mudar a sua escolha quando quiser.', 'gl' => 'Podes cambiar a túa elección cando queiras.'],
    'Necesarias' => ['en' => 'Necessary', 'pt' => 'Necessários', 'gl' => 'Necesarias'],
    'Mantienen tu sesión y recuerdan esta elección. Siempre activas.' => ['en' => 'They keep you signed in and remember this choice. Always on.', 'pt' => 'Mantêm a sua sessão e lembram esta escolha. Sempre ativos.', 'gl' => 'Manteñen a túa sesión e lembran esta elección. Sempre activas.'],
    'Análisis' => ['en' => 'Analytics', 'pt' => 'Análise', 'gl' => 'Análise'],
    'Estadísticas de visitas (Google Analytics).' => ['en' => 'Visit statistics (Google Analytics).', 'pt' => 'Estatísticas de visitas (Google Analytics).', 'gl' => 'Estatísticas de visitas (Google Analytics).'],
    'Publicidad' => ['en' => 'Advertising', 'pt' => 'Publicidade', 'gl' => 'Publicidade'],
    'Desactivada: tu navegador pide no compartir datos (GPC).' => ['en' => 'Off: your browser asks not to share data (GPC).', 'pt' => 'Desativada: o seu navegador pede para não partilhar dados (GPC).', 'gl' => 'Desactivada: o teu navegador pide non compartir datos (GPC).'],
    'Medir anuncios en Google, Instagram o Facebook. Implica compartir datos con esas empresas.' => ['en' => 'Measure ads on Google, Instagram or Facebook. This means sharing data with those companies.', 'pt' => 'Medir anúncios na Google, Instagram ou Facebook. Implica partilhar dados com essas empresas.', 'gl' => 'Medir anuncios en Google, Instagram ou Facebook. Implica compartir datos con esas empresas.'],
    'Rechazar todas' => ['en' => 'Reject all', 'pt' => 'Rejeitar todos', 'gl' => 'Rexeitar todas'],
    'Configurar' => ['en' => 'Settings', 'pt' => 'Configurar', 'gl' => 'Configurar'],
    'Guardar elección' => ['en' => 'Save choice', 'pt' => 'Guardar escolha', 'gl' => 'Gardar elección'],
    'Aceptar todas' => ['en' => 'Accept all', 'pt' => 'Aceitar todos', 'gl' => 'Aceptar todas'],
    'Usamos cookies necesarias para que la web funcione y, si nos das permiso, cookies de análisis para saber cómo se usa la web y mejorarla, y de publicidad para medir nuestros anuncios.' => ['en' => 'We use necessary cookies to make the website work and, with your permission, analytics cookies to understand how the website is used and improve it, and advertising cookies to measure our ads.', 'pt' => 'Usamos cookies necessários para o site funcionar e, com a sua autorização, cookies de análise para saber como o site é usado e melhorá-lo, e de publicidade para medir os nossos anúncios.', 'gl' => 'Usamos cookies necesarias para que a web funcione e, se nos das permiso, cookies de análise para saber como se usa a web e mellorala, e de publicidade para medir os nosos anuncios.'],
    'Usamos cookies necesarias para que la web funcione y, si nos das permiso, cookies de análisis para saber cómo se usa la web y mejorarla.' => ['en' => 'We use necessary cookies to make the website work and, with your permission, analytics cookies to understand how the website is used and improve it.', 'pt' => 'Usamos cookies necessários para o site funcionar e, com a sua autorização, cookies de análise para saber como o site é usado e melhorá-lo.', 'gl' => 'Usamos cookies necesarias para que a web funcione e, se nos das permiso, cookies de análise para saber como se usa a web e mellorala.'],
    'Gluten' => ['en' => 'Gluten', 'pt' => 'Glúten', 'gl' => 'Glute'],
    'Trigo (también espelta y kamut), centeno, cebada, avena y todo lo hecho con ellos: pan, pasta, rebozados, salsas espesadas.' => ['en' => 'Wheat (including spelt and kamut), rye, barley, oats and anything made with them: bread, pasta, batter, thickened sauces.', 'pt' => 'Trigo (também espelta e kamut), centeio, cevada, aveia e tudo o que é feito com eles: pão, massa, panados, molhos espessados.', 'gl' => 'Trigo (tamén espelta e kamut), centeo, cebada, avea e todo o feito con eles: pan, pasta, rebozados, salsas espesadas.'],
    'Crustáceos' => ['en' => 'Crustaceans', 'pt' => 'Crustáceos', 'gl' => 'Crustáceos'],
    'Gambas, langostinos, cigalas, bogavante, nécoras, cangrejos y caldos o salsas que los lleven.' => ['en' => 'Prawns, langoustines, lobster, crabs and any stocks or sauces containing them.', 'pt' => 'Camarão, gambas, lagostins, lavagante, navalheiras, caranguejos e caldos ou molhos que os contenham.', 'gl' => 'Gambas, lagostinos, cigalas, lumbrigante, nécoras, cangrexos e caldos ou salsas que os leven.'],
    'Huevos' => ['en' => 'Eggs', 'pt' => 'Ovos', 'gl' => 'Ovos'],
    'Huevo de cualquier ave y lo elaborado con él: mayonesa, alioli, masas, rebozados, postres.' => ['en' => 'Eggs from any bird and anything made with them: mayonnaise, aioli, doughs, batter, desserts.', 'pt' => 'Ovo de qualquer ave e o que é feito com ele: maionese, alioli, massas, panados, sobremesas.', 'gl' => 'Ovo de calquera ave e o elaborado con el: maionesa, allada, masas, rebozados, sobremesas.'],
    'Pescado' => ['en' => 'Fish', 'pt' => 'Peixe', 'gl' => 'Peixe'],
    'Cualquier pescado y sus derivados, como fumet, caldos o salsas de pescado.' => ['en' => 'Any fish and fish products, such as fish stock or fish sauces.', 'pt' => 'Qualquer peixe e os seus derivados, como fumet, caldos ou molhos de peixe.', 'gl' => 'Calquera peixe e os seus derivados, como fumet, caldos ou salsas de peixe.'],
    'Cacahuetes' => ['en' => 'Peanuts', 'pt' => 'Amendoins', 'gl' => 'Cacahuetes'],
    'Cacahuetes y productos que los contienen, como aceite o crema de cacahuete.' => ['en' => 'Peanuts and products containing them, such as peanut oil or peanut butter.', 'pt' => 'Amendoins e produtos que os contêm, como óleo ou manteiga de amendoim.', 'gl' => 'Cacahuetes e produtos que os conteñen, como aceite ou crema de cacahuete.'],
    'Soja' => ['en' => 'Soya', 'pt' => 'Soja', 'gl' => 'Soia'],
    'Soja y derivados: salsa de soja, tofu, edamame, bebida de soja, lecitina de soja.' => ['en' => 'Soya and soya products: soy sauce, tofu, edamame, soya drink, soya lecithin.', 'pt' => 'Soja e derivados: molho de soja, tofu, edamame, bebida de soja, lecitina de soja.', 'gl' => 'Soia e derivados: salsa de soia, tofu, edamame, bebida de soia, lecitina de soia.'],
    'Lácteos' => ['en' => 'Milk', 'pt' => 'Leite', 'gl' => 'Lácteos'],
    'Leche de cualquier animal y derivados, incluida la lactosa: nata, mantequilla, queso, yogur.' => ['en' => 'Milk from any animal and dairy products, including lactose: cream, butter, cheese, yoghurt.', 'pt' => 'Leite de qualquer animal e derivados, incluindo a lactose: natas, manteiga, queijo, iogurte.', 'gl' => 'Leite de calquera animal e derivados, incluída a lactosa: nata, manteiga, queixo, iogur.'],
    'Frutos de cáscara' => ['en' => 'Tree nuts', 'pt' => 'Frutos de casca rija', 'gl' => 'Froitos de casca'],
    'Almendras, avellanas, nueces, anacardos, pacanas, pistachos, macadamias y nueces de Brasil.' => ['en' => 'Almonds, hazelnuts, walnuts, cashews, pecans, pistachios, macadamias and Brazil nuts.', 'pt' => 'Amêndoas, avelãs, nozes, cajus, nozes-pecã, pistácios, macadâmias e castanhas-do-pará.', 'gl' => 'Améndoas, abelás, noces, anacardos, pacanas, pistachos, macadamias e noces do Brasil.'],
    'Apio' => ['en' => 'Celery', 'pt' => 'Aipo', 'gl' => 'Apio'],
    'Apio en rama, en raíz o como especia, y caldos, sopas o sofritos que lo lleven.' => ['en' => 'Celery stalks, root or as a spice, and any stocks, soups or sofritos containing it.', 'pt' => 'Aipo em rama, em raiz ou como especiaria, e caldos, sopas ou refogados que o contenham.', 'gl' => 'Apio en rama, en raíz ou como especia, e caldos, sopas ou refritos que o leven.'],
    'Mostaza' => ['en' => 'Mustard', 'pt' => 'Mostarda', 'gl' => 'Mostaza'],
    'Mostaza en grano, en polvo o en salsa, y aliños o vinagretas que la contengan.' => ['en' => 'Mustard seeds, powder or sauce, and any dressings or vinaigrettes containing it.', 'pt' => 'Mostarda em grão, em pó ou em molho, e temperos ou vinagretes que a contenham.', 'gl' => 'Mostaza en gran, en po ou en salsa, e aliños ou vinagretas que a conteñan.'],
    'Sésamo' => ['en' => 'Sesame', 'pt' => 'Sésamo', 'gl' => 'Sésamo'],
    'Granos y aceite de sésamo, tahini, y panes o salsas que lo lleven.' => ['en' => 'Sesame seeds and oil, tahini, and any breads or sauces containing it.', 'pt' => 'Sementes e óleo de sésamo, tahini, e pães ou molhos que o contenham.', 'gl' => 'Grans e aceite de sésamo, tahini, e pans ou salsas que o leven.'],
    'Sulfitos' => ['en' => 'Sulphites', 'pt' => 'Sulfitos', 'gl' => 'Sulfitos'],
    'Dióxido de azufre y sulfitos (más de 10 mg/kg). Suelen estar en el vino, la cerveza, la sidra y algunos encurtidos.' => ['en' => 'Sulphur dioxide and sulphites (over 10 mg/kg). Usually found in wine, beer, cider and some pickles.', 'pt' => 'Dióxido de enxofre e sulfitos (mais de 10 mg/kg). Costumam estar no vinho, na cerveja, na sidra e em alguns pickles.', 'gl' => 'Dióxido de xofre e sulfitos (máis de 10 mg/kg). Adoitan estar no viño, a cervexa, a sidra e algúns encurtidos.'],
    'Altramuces' => ['en' => 'Lupin', 'pt' => 'Tremoço', 'gl' => 'Chícharos de raposo'],
    'Altramuces y harinas o productos elaborados con ellos.' => ['en' => 'Lupin and flours or products made with it.', 'pt' => 'Tremoço e farinhas ou produtos feitos com ele.', 'gl' => 'Chícharos de raposo (altramuces) e fariñas ou produtos elaborados con eles.'],
    'Moluscos' => ['en' => 'Molluscs', 'pt' => 'Moluscos', 'gl' => 'Moluscos'],
    'Mejillones, almejas, ostras, vieiras, zamburiñas, pulpo, calamar, sepia y caracoles.' => ['en' => 'Mussels, clams, oysters, scallops, queen scallops, octopus, squid, cuttlefish and snails.', 'pt' => 'Mexilhões, amêijoas, ostras, vieiras, zamburinhas, polvo, lula, choco e caracóis.', 'gl' => 'Mexillóns, ameixas, ostras, vieiras, zamburiñas, polbo, lura, xiba e caracois.'],
    'Fecha no válida' => ['en' => 'Invalid date', 'pt' => 'Data inválida', 'gl' => 'Data non válida'],
    'Escribe un nombre' => ['en' => 'Enter a name', 'pt' => 'Escreva um nome', 'gl' => 'Escribe un nome'],
    'El teléfono no parece correcto' => ['en' => 'The phone number doesn’t look right', 'pt' => 'O telefone não parece correto', 'gl' => 'O teléfono non parece correcto'],
    'El email no parece correcto' => ['en' => 'The email doesn’t look right', 'pt' => 'O email não parece correto', 'gl' => 'O correo non parece correcto'],
    'Hora no válida' => ['en' => 'Invalid time', 'pt' => 'Hora inválida', 'gl' => 'Hora non válida'],
    'No se pudo enviar' => ['en' => 'It couldn’t be sent', 'pt' => 'Não foi possível enviar', 'gl' => 'Non se puido enviar'],
    'Tienes que aceptar las políticas de reserva y de privacidad' => ['en' => 'You need to accept the booking and privacy policies', 'pt' => 'Tem de aceitar as políticas de reserva e de privacidade', 'gl' => 'Tes que aceptar as políticas de reserva e de privacidade'],
    'Has hecho demasiadas reservas seguidas. Llámanos por teléfono.' => ['en' => 'You’ve made too many bookings in a row. Please call us.', 'pt' => 'Fez demasiadas reservas seguidas. Ligue-nos.', 'gl' => 'Fixeches demasiadas reservas seguidas. Chámanos por teléfono.'],
