    '1 reserva' => ['en' => '1 booking', 'pt' => '1 reserva', 'gl' => '1 reserva'],
    '%d reservas' => ['en' => '%d bookings', 'pt' => '%d reservas', 'gl' => '%d reservas'],
    '1 aún no ha pasado y se cancelará' => ['en' => '1 is still upcoming and will be cancelled', 'pt' => '1 ainda não passou e será cancelada', 'gl' => '1 aínda non pasou e cancelarase'],
    '%d aún no han pasado y se cancelarán' => ['en' => '%d are still upcoming and will be cancelled', 'pt' => '%d ainda não passaram e serão canceladas', 'gl' => '%d aínda non pasaron e cancelaranse'],
    'No se puede deshacer. De las reservas solo quedarán el día, la hora y el número de personas, sin nada que te identifique.' => ['en' => 'This cannot be undone. Only the date, time and number of people of each booking will remain, with nothing that identifies you.', 'pt' => 'Não se pode desfazer. Das reservas só ficarão o dia, a hora e o número de pessoas, sem nada que o identifique.', 'gl' => 'Non se pode desfacer. Das reservas só quedarán o día, a hora e o número de persoas, sen nada que te identifique.'],
    'No, volver' => ['en' => 'No, go back', 'pt' => 'Não, voltar', 'gl' => 'Non, volver'],
    'Este enlace ya no funciona' => ['en' => 'This link no longer works', 'pt' => 'Este link já não funciona', 'gl' => 'Esta ligazón xa non funciona'],
    'Puede que ya lo hayas usado o que haya caducado. Puedes pedir otro aquí abajo.' => ['en' => 'You may have used it already or it may have expired. You can request another one below.', 'pt' => 'Pode já o ter usado ou ter expirado. Pode pedir outro aqui em baixo.', 'gl' => 'Pode que xa a usases ou que caducase. Podes pedir outra aquí abaixo.'],
    'Escribe el email o el teléfono con el que reservaste o te registraste.' => ['en' => 'Enter the email or phone number you used to book or sign up.', 'pt' => 'Escreva o email ou o telefone com que reservou ou se registou.', 'gl' => 'Escribe o email ou o teléfono co que reservaches ou te rexistraches.'],
    'Escribe tu email o tu teléfono.' => ['en' => 'Enter your email or phone number.', 'pt' => 'Escreva o seu email ou telefone.', 'gl' => 'Escribe o teu email ou o teu teléfono.'],
    'Ese email no parece correcto.' => ['en' => 'That email doesn\'t look right.', 'pt' => 'Esse email não parece correto.', 'gl' => 'Ese email non parece correcto.'],
    'Ese teléfono no parece correcto.' => ['en' => 'That phone number doesn\'t look right.', 'pt' => 'Esse telefone não parece correto.', 'gl' => 'Ese teléfono non parece correcto.'],
    'Demasiados intentos. Espera una hora.' => ['en' => 'Too many attempts. Please wait an hour.', 'pt' => 'Demasiadas tentativas. Aguarde uma hora.', 'gl' => 'Demasiados intentos. Agarda unha hora.'],
    'Si tenemos datos con ese email, te hemos enviado un enlace para confirmar el borrado. Mira también en spam.' => ['en' => 'If we have data with that email, we have sent you a link to confirm the deletion. Check your spam folder too.', 'pt' => 'Se tivermos dados com esse email, enviámos-lhe um link para confirmar a eliminação. Veja também no spam.', 'gl' => 'Se temos datos con ese email, enviámosche unha ligazón para confirmar o borrado. Mira tamén no spam.'],
    'Si tenemos datos con ese teléfono, te enviaremos por WhatsApp un enlace para confirmar el borrado.' => ['en' => 'If we have data with that phone number, we will send you a WhatsApp link to confirm the deletion.', 'pt' => 'Se tivermos dados com esse telefone, enviaremos por WhatsApp um link para confirmar a eliminação.', 'gl' => 'Se temos datos con ese teléfono, enviarémosche por WhatsApp unha ligazón para confirmar o borrado.'],
    'Borrar tus datos de %s' => ['en' => 'Delete your data from %s', 'pt' => 'Apagar os seus dados de %s', 'gl' => 'Borrar os teus datos de %s'],
    'Hola:' => ['en' => 'Hello,', 'pt' => 'Olá,', 'gl' => 'Ola:'],
    'Hemos recibido una petición para borrar todos los datos que %s guarda con este email (cuenta, reservas y registro de actividad). Si has sido tú, abre este enlace y pulsa «Borrar mis datos»:' => ['en' => 'We have received a request to delete all the data %s keeps with this email (account, bookings and activity log). If it was you, open this link and press “Delete my data”:', 'pt' => 'Recebemos um pedido para apagar todos os dados que %s guarda com este email (conta, reservas e registo de atividade). Se foi você, abra este link e carregue em «Apagar os meus dados»:', 'gl' => 'Recibimos unha petición para borrar todos os datos que %s garda con este email (conta, reservas e rexistro de actividade). Se fuches ti, abre esta ligazón e preme «Borrar os meus datos»:'],
    'El enlace caduca en %d horas. Si no has sido tú, ignora este mensaje: no se borrará nada.' => ['en' => 'The link expires in %d hours. If it wasn\'t you, ignore this message: nothing will be deleted.', 'pt' => 'O link expira em %d horas. Se não foi você, ignore esta mensagem: nada será apagado.', 'gl' => 'A ligazón caduca en %d horas. Se non fuches ti, ignora esta mensaxe: non se borrará nada.'],
    'Hola, somos %s. Nos has pedido borrar todos tus datos. Para confirmarlo, abre este enlace y pulsa «Borrar mis datos»:' => ['en' => 'Hi, this is %s. You asked us to delete all your data. To confirm, open this link and press “Delete my data”:', 'pt' => 'Olá, somos o %s. Pediu-nos para apagar todos os seus dados. Para confirmar, abra este link e carregue em «Apagar os meus dados»:', 'gl' => 'Ola, somos %s. Pedíchesnos borrar todos os teus datos. Para confirmalo, abre esta ligazón e preme «Borrar os meus datos»:'],
    'El enlace caduca en %d horas.' => ['en' => 'The link expires in %d hours.', 'pt' => 'O link expira em %d horas.', 'gl' => 'A ligazón caduca en %d horas.'],
    'Hola %s, somos %s. Lo sentimos: no tenemos mesa para %s el %s a las %s.' => ['en' => 'Hi %s, this is %s. We\'re sorry: we don\'t have a table for %s on %s at %s.', 'pt' => 'Olá %s, somos o %s. Lamentamos: não temos mesa para %s no dia %s às %s.', 'gl' => 'Ola %s, somos %s. Sentímolo: non temos mesa para %s o %s ás %s.'],
    'Ese día sí tenemos sitio a estas horas: %s. Si te va bien alguna, haz la reserva en la web:' => ['en' => 'That day we do have tables at these times: %s. If any of them suits you, book on our website:', 'pt' => 'Nesse dia temos lugar a estas horas: %s. Se alguma lhe der jeito, faça a reserva no site:', 'gl' => 'Ese día si temos sitio a estas horas: %s. Se che vai ben algunha, fai a reserva na web:'],
    'Ese día ya no nos queda sitio. Esperamos verte otro día; puedes reservar en la web:' => ['en' => 'We\'re fully booked that day. We hope to see you another day; you can book on our website:', 'pt' => 'Nesse dia já não temos lugar. Esperamos vê-lo noutro dia; pode reservar no site:', 'gl' => 'Ese día xa non nos queda sitio. Esperamos verte outro día; podes reservar na web:'],
    'Tu email o tu teléfono' => ['en' => 'Your email or phone number', 'pt' => 'O seu email ou telefone', 'gl' => 'O teu email ou o teu teléfono'],
    'ejemplo@correo.com o 600 123 456' => ['en' => 'name@email.com or 600 123 456', 'pt' => 'exemplo@correio.com ou 600 123 456', 'gl' => 'exemplo@correo.com ou 600 123 456'],
    'Borraremos tu cuenta, tus reservas y el registro de actividad. Las reservas que aún no hayan pasado se cancelarán. Para que nadie pueda borrar los datos de otra persona, te enviaremos un enlace para confirmarlo: por email si escribes tu email, o por WhatsApp si escribes tu teléfono.' => ['en' => 'We will delete your account, your bookings and the activity log. Upcoming bookings will be cancelled. So that nobody can delete someone else\'s data, we will send you a link to confirm it: by email if you enter your email, or by WhatsApp if you enter your phone number.', 'pt' => 'Apagaremos a sua conta, as suas reservas e o registo de atividade. As reservas que ainda não passaram serão canceladas. Para que ninguém possa apagar os dados de outra pessoa, enviaremos um link para confirmar: por email se escrever o seu email, ou por WhatsApp se escrever o seu telefone.', 'gl' => 'Borraremos a túa conta, as túas reservas e o rexistro de actividade. As reservas que aínda non pasaran cancelaranse. Para que ninguén poida borrar os datos doutra persoa, enviarémosche unha ligazón para confirmalo: por email se escribes o teu email, ou por WhatsApp se escribes o teu teléfono.'],
    'Borrar todos mis datos' => ['en' => 'Delete all my data', 'pt' => 'Apagar todos os meus dados', 'gl' => 'Borrar todos os meus datos'],
    // Recuperar la contraseña
    'Recuperar la contraseña' => ['en' => 'Reset your password', 'pt' => 'Recuperar a palavra-passe', 'gl' => 'Recuperar o contrasinal'],
    '¿Has olvidado la contraseña?' => ['en' => 'Forgotten your password?', 'pt' => 'Esqueceu-se da palavra-passe?', 'gl' => 'Esqueciches o contrasinal?'],
    'Escribe el email de tu cuenta y te enviaremos un enlace para elegir una contraseña nueva.' => ['en' => 'Enter your account email and we’ll send you a link to choose a new password.', 'pt' => 'Escreva o email da sua conta e enviaremos uma ligação para escolher uma nova palavra-passe.', 'gl' => 'Escribe o correo da túa conta e enviarémosche unha ligazón para escoller un contrasinal novo.'],
    'Enviar el enlace' => ['en' => 'Send the link', 'pt' => 'Enviar a ligação', 'gl' => 'Enviar a ligazón'],
    'Si hay una cuenta con ese email, te hemos enviado un enlace. Caduca en 1 hora. Si no lo ves, mira en la carpeta de spam.' => ['en' => 'If there is an account with that email, we’ve sent you a link. It expires in 1 hour. If you can’t see it, check your spam folder.', 'pt' => 'Se existir uma conta com esse email, enviámos-lhe uma ligação. Expira em 1 hora. Se não a vir, veja na pasta de spam.', 'gl' => 'Se hai unha conta con ese correo, enviámosche unha ligazón. Caduca nunha hora. Se non a ves, mira no cartafol de spam.'],
    'Elige una contraseña nueva' => ['en' => 'Choose a new password', 'pt' => 'Escolha uma nova palavra-passe', 'gl' => 'Escolle un contrasinal novo'],
    'Guardar y entrar' => ['en' => 'Save and sign in', 'pt' => 'Guardar e entrar', 'gl' => 'Gardar e entrar'],
    'Volver a entrar' => ['en' => 'Back to sign in', 'pt' => 'Voltar a entrar', 'gl' => 'Volver entrar'],
    'Cambia tu contraseña en %s' => ['en' => 'Change your password at %s', 'pt' => 'Altere a sua palavra-passe em %s', 'gl' => 'Cambia o teu contrasinal en %s'],
    'Para elegir una contraseña nueva abre este enlace (caduca en 1 hora y solo sirve una vez):' => ['en' => 'To choose a new password, open this link (it expires in 1 hour and only works once):', 'pt' => 'Para escolher uma nova palavra-passe, abra esta ligação (expira em 1 hora e só funciona uma vez):', 'gl' => 'Para escoller un contrasinal novo abre esta ligazón (caduca nunha hora e só serve unha vez):'],
    'Si no lo has pedido tú, ignora este email: tu contraseña sigue igual.' => ['en' => 'If you didn’t ask for this, ignore this email: your password stays the same.', 'pt' => 'Se não foi o próprio a pedir, ignore este email: a sua palavra-passe continua igual.', 'gl' => 'Se non o pediches ti, ignora este correo: o teu contrasinal segue igual.'],
    'El enlace para cambiar la contraseña no es válido o ha caducado. Pide otro.' => ['en' => 'The password reset link is not valid or has expired. Ask for a new one.', 'pt' => 'A ligação para alterar a palavra-passe não é válida ou expirou. Peça outra.', 'gl' => 'A ligazón para cambiar o contrasinal non é válida ou caducou. Pide outra.'],
    // Fisioterapia: textos de la web y del cuadro de cita
    'Pedir cita' => ['en' => 'Book an appointment', 'pt' => 'Marcar consulta', 'gl' => 'Pedir cita'],
    'Pedir cita online' => ['en' => 'Book online', 'pt' => 'Marcar consulta online', 'gl' => 'Pedir cita en liña'],
    'Elige tratamiento, día y hora y te confirmamos por WhatsApp.' => ['en' => 'Choose a treatment, day and time and we will confirm on WhatsApp.', 'pt' => 'Escolha o tratamento, o dia e a hora e confirmamos pelo WhatsApp.', 'gl' => 'Escolle tratamento, día e hora e confirmámosche por WhatsApp.'],
    'Pregúntanos o pide cita por mensaje.' => ['en' => 'Ask us or book by message.', 'pt' => 'Pergunte-nos ou marque por mensagem.', 'gl' => 'Pregúntanos ou pide cita por mensaxe.'],
    '¿Qué necesitas?' => ['en' => 'What do you need?', 'pt' => 'Do que precisa?', 'gl' => 'Que necesitas?'],
    'Dónde te duele, desde cuándo, si vienes de parte de tu médico…' => ['en' => 'Where it hurts, since when, whether your doctor referred you…', 'pt' => 'Onde dói, desde quando, se vem da parte do seu médico…', 'gl' => 'Onde che doe, dende cando, se vés da parte do teu médico…'],
    'Cancelar desde el enlace es gratis. Si no puedes venir, avísanos con tiempo para dar tu hueco a otra persona.' => ['en' => 'Cancelling from the link is free. If you cannot come, let us know in time so we can give your slot to someone else.', 'pt' => 'Cancelar a partir da ligação é gratuito. Se não puder vir, avise-nos com tempo para darmos a sua vaga a outra pessoa.', 'gl' => 'Cancelar dende a ligazón é gratis. Se non podes vir, avísanos con tempo para darlle o teu oco a outra persoa.'],
    '<strong>Protección de datos.</strong> Responsable: %s. Finalidad: gestionar tu cita; el teléfono solo se usa para enviarte el WhatsApp de confirmación. Los datos de la petición se borran 24 horas después de la cita y no se ceden a nadie; si eres paciente del centro, tu ficha clínica se guarda aparte el tiempo que marca la ley. Puedes acceder a ellos, corregirlos o borrarlos escribiendo a %s.' => ['en' => '<strong>Data protection.</strong> Controller: %s. Purpose: managing your appointment; your phone number is only used to send you the WhatsApp confirmation. Request data is deleted 24 hours after the appointment and is never shared; if you are a patient of the centre, your clinical record is kept separately for as long as the law requires. You can access, correct or delete your data by writing to %s.', 'pt' => '<strong>Proteção de dados.</strong> Responsável: %s. Finalidade: gerir a sua consulta; o telefone só é usado para lhe enviar o WhatsApp de confirmação. Os dados do pedido são apagados 24 horas após a consulta e não são cedidos a ninguém; se for paciente do centro, a sua ficha clínica é guardada à parte durante o tempo que a lei exige. Pode aceder aos seus dados, corrigi-los ou apagá-los escrevendo para %s.', 'gl' => '<strong>Protección de datos.</strong> Responsable: %s. Finalidade: xestionar a túa cita; o teléfono só se usa para enviarche o WhatsApp de confirmación. Os datos da petición bórranse 24 horas despois da cita e non se ceden a ninguén; se es paciente do centro, a túa ficha clínica gárdase á parte o tempo que marca a lei. Podes acceder a eles, corrixilos ou borralos escribindo a %s.'],
    'Pides cita como' => ['en' => 'Booking as', 'pt' => 'Marca como', 'gl' => 'Pides cita como'],
    'Ponlo si quieres recibir la confirmación por email o ver esta cita en una cuenta: solo aparecerá en la cuenta que crees con este mismo email. Sin email, la cita no se puede añadir a una cuenta.' => ['en' => 'Add it if you want the confirmation by email or to see this appointment in an account: it will only appear in an account created with this same email. Without an email, the appointment cannot be added to an account.', 'pt' => 'Indique-o se quiser receber a confirmação por email ou ver esta consulta numa conta: só aparecerá na conta que criar com este mesmo email. Sem email, a consulta não pode ser adicionada a uma conta.', 'gl' => 'Ponlo se queres recibir a confirmación por correo ou ver esta cita nunha conta: só aparecerá na conta que crees con este mesmo correo. Sen correo, a cita non se pode engadir a unha conta.'],
    'Acepto las <a href="legal.php#politicas" target="_blank">normas del centro</a> y las <a href="legal.php#condiciones" target="_blank">condiciones de uso</a>, y he leído la <a href="legal.php#privacidad" target="_blank">política de privacidad</a>.' => ['en' => 'I accept the <a href="legal.php#politicas" target="_blank">centre rules</a> and the <a href="legal.php#condiciones" target="_blank">terms of use</a>, and I have read the <a href="legal.php#privacidad" target="_blank">privacy policy</a>.', 'pt' => 'Aceito as <a href="legal.php#politicas" target="_blank">normas do centro</a> e as <a href="legal.php#condiciones" target="_blank">condições de utilização</a>, e li a <a href="legal.php#privacidad" target="_blank">política de privacidade</a>.', 'gl' => 'Acepto as <a href="legal.php#politicas" target="_blank">normas do centro</a> e as <a href="legal.php#condiciones" target="_blank">condicións de uso</a>, e lin a <a href="legal.php#privacidad" target="_blank">política de privacidade</a>.'],
    'Ese día el centro está cerrado' => ['en' => 'The centre is closed that day', 'pt' => 'Nesse dia o centro está fechado', 'gl' => 'Ese día o centro está pechado'],
    'Ese día el centro no abre' => ['en' => 'The centre does not open that day', 'pt' => 'Nesse dia o centro não abre', 'gl' => 'Ese día o centro non abre'],
    'Ese día ya no quedan huecos libres' => ['en' => 'There are no free slots left that day', 'pt' => 'Nesse dia já não há vagas', 'gl' => 'Ese día xa non quedan ocos libres'],
    'Elige primero un tratamiento' => ['en' => 'Choose a treatment first', 'pt' => 'Escolha primeiro um tratamento', 'gl' => 'Escolle primeiro un tratamento'],
    'Mañana' => ['en' => 'Morning', 'pt' => 'Manhã', 'gl' => 'Mañá'],
    'Tarde' => ['en' => 'Afternoon', 'pt' => 'Tarde', 'gl' => 'Tarde'],
    'cita' => ['en' => 'appointment', 'pt' => 'consulta', 'gl' => 'cita'],
    'El centro la revisará y te enviará un WhatsApp al %s con un enlace para confirmarla.' => ['en' => 'The centre will review it and send a WhatsApp to %s with a link to confirm it.', 'pt' => 'O centro vai analisá-la e enviar um WhatsApp para o %s com uma ligação para a confirmar.', 'gl' => 'O centro revisaraa e enviarache un WhatsApp ao %s cunha ligazón para confirmala.'],
    'Ya tienes %d citas pendientes o confirmadas. Para pedir otra, cancela alguna o llámanos.' => ['en' => 'You already have %d pending or confirmed appointments. To book another, cancel one or call us.', 'pt' => 'Já tem %d consultas pendentes ou confirmadas. Para marcar outra, cancele alguma ou ligue-nos.', 'gl' => 'Xa tes %d citas pendentes ou confirmadas. Para pedir outra, cancela algunha ou chámanos.'],
    'Hola %s, confirma tu cita en %s para el %s a las %s (%s). Abre este enlace y pulsa «Confirmar mi cita»:' => ['en' => 'Hi %s, please confirm your appointment at %s on %s at %s (%s). Open this link and tap “Confirm my appointment”:', 'pt' => 'Olá %s, confirme a sua consulta em %s para %s às %s (%s). Abra esta ligação e toque em «Confirmar a minha consulta»:', 'gl' => 'Ola %s, confirma a túa cita en %s para o %s ás %s (%s). Abre esta ligazón e preme «Confirmar a miña cita»:'],
    'Confirma tu cita en %s' => ['en' => 'Confirm your appointment at %s', 'pt' => 'Confirme a sua consulta em %s', 'gl' => 'Confirma a túa cita en %s'],
    'Tenemos hueco para ti el %s. Para confirmar la cita, abre este enlace y pulsa «Confirmar mi cita»:' => ['en' => 'We have a slot for you on %s. To confirm the appointment, open this link and tap “Confirm my appointment”:', 'pt' => 'Temos vaga para si em %s. Para confirmar a consulta, abra esta ligação e toque em «Confirmar a minha consulta»:', 'gl' => 'Temos oco para ti o %s. Para confirmar a cita, abre esta ligazón e preme «Confirmar a miña cita»:'],
    'También te lo hemos enviado por WhatsApp. Si te has equivocado en algún dato, vuelve a pedir la cita en la web.' => ['en' => 'We have also sent it to you on WhatsApp. If any detail is wrong, book again on the website.', 'pt' => 'Também lho enviámos pelo WhatsApp. Se algum dado estiver errado, volte a marcar no site.', 'gl' => 'Tamén cho enviamos por WhatsApp. Se te equivocaches nalgún dato, volve pedir a cita na web.'],
    'Cita confirmada en %s' => ['en' => 'Appointment confirmed at %s', 'pt' => 'Consulta confirmada em %s', 'gl' => 'Cita confirmada en %s'],
    'Tu cita del %s está confirmada. Ven con ropa cómoda. ¡Te esperamos!' => ['en' => 'Your appointment on %s is confirmed. Wear comfortable clothes. See you soon!', 'pt' => 'A sua consulta de %s está confirmada. Venha com roupa confortável. Esperamos por si!', 'gl' => 'A túa cita do %s está confirmada. Ven con roupa cómoda. Agardámoste!'],
    'No podemos atenderte a esa hora en %s' => ['en' => 'We cannot see you at that time at %s', 'pt' => 'Não o podemos atender a essa hora em %s', 'gl' => 'Non podemos atenderte a esa hora en %s'],
    'Lo sentimos, no tenemos hueco libre el %s.' => ['en' => 'Sorry, we have no free slot on %s.', 'pt' => 'Lamentamos, não temos vaga em %s.', 'gl' => 'Sentímolo, non temos oco libre o %s.'],
    'Cita cancelada en %s' => ['en' => 'Appointment cancelled at %s', 'pt' => 'Consulta cancelada em %s', 'gl' => 'Cita cancelada en %s'],
    'Tu cita del %s ha quedado cancelada.' => ['en' => 'Your appointment on %s has been cancelled.', 'pt' => 'A sua consulta de %s foi cancelada.', 'gl' => 'A túa cita do %s quedou cancelada.'],
    'Hola %s, somos %s. Lo sentimos: no tenemos hueco el %s a las %s.' => ['en' => 'Hi %s, this is %s. Sorry: we have no slot on %s at %s.', 'pt' => 'Olá %s, somos o %s. Lamentamos: não temos vaga em %s às %s.', 'gl' => 'Ola %s, somos %s. Sentímolo: non temos oco o %s ás %s.'],
    'Ese día sí tenemos hueco a estas horas: %s. Si te va bien alguna, pide la cita en la web:' => ['en' => 'That day we do have slots at these times: %s. If one suits you, book on the website:', 'pt' => 'Nesse dia temos vaga a estas horas: %s. Se alguma lhe der jeito, marque no site:', 'gl' => 'Ese día si temos oco a estas horas: %s. Se che vai ben algunha, pide a cita na web:'],
    'Ese día ya no nos queda hueco. Puedes pedir cita para otro día en la web:' => ['en' => 'We have no slots left that day. You can book another day on the website:', 'pt' => 'Nesse dia já não temos vagas. Pode marcar para outro dia no site:', 'gl' => 'Ese día xa non nos queda oco. Podes pedir cita para outro día na web:'],
    'Cita confirmada' => ['en' => 'Appointment confirmed', 'pt' => 'Consulta confirmada', 'gl' => 'Cita confirmada'],
    'Cita cancelada' => ['en' => 'Appointment cancelled', 'pt' => 'Consulta cancelada', 'gl' => 'Cita cancelada'],
    '¿Cancelar la cita?' => ['en' => 'Cancel the appointment?', 'pt' => 'Cancelar a consulta?', 'gl' => 'Cancelar a cita?'],
    '¿Cancelar la cita del %s?' => ['en' => 'Cancel the appointment on %s?', 'pt' => 'Cancelar a consulta de %s?', 'gl' => 'Cancelar a cita do %s?'],
    'Esperando confirmación. Mientras no abras el enlace del WhatsApp y pulses «Confirmar mi cita», la cita queda pendiente.' => ['en' => 'Waiting for confirmation. Until you open the WhatsApp link and tap “Confirm my appointment”, the appointment stays pending.', 'pt' => 'À espera de confirmação. Enquanto não abrir a ligação do WhatsApp e tocar em «Confirmar a minha consulta», a consulta fica pendente.', 'gl' => 'Agardando confirmación. Mentres non abras a ligazón do WhatsApp e premas «Confirmar a miña cita», a cita queda pendente.'],
    'Como no has puesto email, esta cita no aparecerá en ninguna cuenta.' => ['en' => 'As you did not give an email, this appointment will not appear in any account.', 'pt' => 'Como não indicou email, esta consulta não aparecerá em nenhuma conta.', 'gl' => 'Como non puxeches correo, esta cita non aparecerá en ningunha conta.'],
    'Demasiadas peticiones. Espera un minuto.' => ['en' => 'Too many requests. Wait a minute.', 'pt' => 'Demasiados pedidos. Aguarde um minuto.', 'gl' => 'Demasiadas peticións. Agarda un minuto.'],
    'Ya tienes una cuenta en %s' => ['en' => 'You already have an account at %s', 'pt' => 'Já tem uma conta em %s', 'gl' => 'Xa tes unha conta en %s'],
    'Alguien (seguramente tú) ha intentado crear una cuenta con este email, pero ya tienes una. Entra con tu contraseña o, si no la recuerdas, pide una nueva aquí:' => ['en' => 'Someone (probably you) tried to create an account with this email, but you already have one. Sign in with your password or, if you do not remember it, request a new one here:', 'pt' => 'Alguém (provavelmente você) tentou criar uma conta com este email, mas já tem uma. Entre com a sua palavra-passe ou, se não se lembrar, peça uma nova aqui:', 'gl' => 'Alguén (seguramente ti) intentou crear unha conta con este correo, pero xa tes unha. Entra co teu contrasinal ou, se non o lembras, pide un novo aquí:'],
    'Si no has sido tú, ignora este email: tu cuenta sigue igual.' => ['en' => 'If it was not you, ignore this email: your account is unchanged.', 'pt' => 'Se não foi você, ignore este email: a sua conta continua igual.', 'gl' => 'Se non fuches ti, ignora este correo: a túa conta segue igual.'],
];
